def sha256_file(p, buf=1 << 20):
    h = hashlib.sha256()
    with open(p, "rb") as f:
        for c in iter(lambda: f.read(buf), b""):
            h.update(c)
    return h.hexdigest()


def digest(names):
    out = {}
    for n in names:
        p = os.path.join(HERE, n)
        out[n] = ({"sha256": sha256_file(p), "bytes": os.path.getsize(p)}
                  if os.path.isfile(p) else {"sha256": "MISSING"})
    return out


def jload(n):
    p = os.path.join(HERE, n)
    return json.load(open(p, encoding="utf-8")) if os.path.isfile(p) else {}


