def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--verify", action="store_true")
    a = ap.parse_args()
    if a.verify:
        if not os.path.isfile(OUT):
            print("NOT LOCKED: %s does not exist" % os.path.basename(OUT))
            return 1
        rec = json.load(open(OUT, encoding="utf-8"))
        drift = 0
        for group, names in rec["artifact_hashes"].items():
            for n, v in names.items():
                p = os.path.join(HERE, n)
                cur = sha256_file(p) if os.path.isfile(p) else "MISSING"
                if cur != v["sha256"]:
                    drift += 1
                    print("PUBLICATION DRIFT %-28s frozen=%s now=%s"
                          % (n, v["sha256"][:16], cur[:16]))
        print("publication artifacts verified: %d"
              % sum(len(v) for v in rec["artifact_hashes"].values()))
        print("publication drift: %d" % drift)
        return 1 if drift else 0

    m = build()
    body = json.dumps(m, indent=1, ensure_ascii=False)
    open(OUT, "w", encoding="utf-8").write(body)
    self_sha = hashlib.sha256(body.encode("utf-8")).hexdigest()
    m["manifest_sha256"] = self_sha
    open(OUT, "w", encoding="utf-8").write(
        json.dumps(m, indent=1, ensure_ascii=False))
    print("PUBLICATION MANIFEST WRITTEN")
    print("  status            %s" % m["status"])
    print("  arms offline      %d   streamed %d"
          % (m["arms"]["n_offline"], m["arms"]["n_streamed"]))
    print("  Q5 labels         %s" % m["results_summary"]["q5"]["n_labels"])
    print("  artifacts hashed  %d"
          % sum(len(v) for v in m["artifact_hashes"].values()))
    missing = [n for g in m["artifact_hashes"].values()
               for n, v in g.items() if v["sha256"] == "MISSING"]
    print("  MISSING artifacts %d %s" % (len(missing), missing))
    print("  manifest sha256   %s" % self_sha)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
